#!/bin/sh
# SUPERSEDED 2026-08-31 -- THIS IS NO LONGER THE LIVE GENERATOR.
# BadEncCountermodel.ec was promoted into the certified closure; the controls the
# gate actually runs are scratch/badenc_ctl{A,B,C,D}.ec, regenerated by
# scratch/mkctl_badenc_split.sh and registered in cert-controls-split.tsv.
# Running THIS script rewrites four files that nothing gates.  It is kept so the
# experiment reproduces as recorded in RESULT.md.
#
# Regenerate the three MUST-FAIL negative controls from base/BadEncCountermodel.ec.
# Each replaces exactly ONE hypothesis of badenc_game_hoare + badenc_is_one by
# `true`, keeping the proof script's intro arity, so the control deletes
# information rather than breaking the syntax.  All three MUST fail to compile.
set -eu
cd "$(dirname "$0")"
mkdir -p controls
banner() {
cat <<'EOF'
(* #########################################################################
   MUST-FAIL NEGATIVE CONTROL -- NOT A RESULT.  DO NOT PROMOTE OR VENDOR.
   Generated by ../mkctl.sh from ../base/BadEncCountermodel.ec with exactly one
   hypothesis of `badenc_game_hoare` / `badenc_is_one` replaced by `true`.
   THIS FILE IS EXPECTED TO FAIL TO COMPILE.  A green compile here would mean
   the corresponding hypothesis is NOT load-bearing, i.e. the real theorem is
   weaker (or more vacuous) than it looks.  Receipts: controls/Ctl?.out.
   SUPERSEDED 2026-08-31: the LIVE controls are scratch/badenc_ctl{A,B,C,D}.ec,
   generated by scratch/mkctl_badenc_split.sh.  Nothing gates the files here.
   ######################################################################### *)
EOF
}
gen() { # $1 = name, $2 = replacement hypothesis line
  { banner; sed "s|^     P cm => cm <> cm' => encode_msgWOTS cm = encode_msgWOTS cm'$|$2|" base/BadEncCountermodel.ec; } > "controls/$1.ec"
}
gen CtlA "     P cm => cm <> cm' => true"
gen CtlB "     P cm => true => encode_msgWOTS cm = encode_msgWOTS cm'"
gen CtlC "     true => cm <> cm' => encode_msgWOTS cm = encode_msgWOTS cm'"
# CtlD mutates the CONCLUSION (1%r -> 0%r) instead of a hypothesis: it checks
# that `conseq badenc_game_ll (badenc_game_hoare ...)` really proves the stated
# probability and is not closing something vacuous.
{ banner; sed "s|: res /\\\\ BadEncFlag.badenc\] = 1%r.|: res /\\\\ BadEncFlag.badenc] = 0%r.|" base/BadEncCountermodel.ec; } > controls/CtlD.ec
chmod 666 controls/*.ec
